import{_ as s,o as a,c as i,a2 as n}from"./chunks/framework.XXezeKOl.js";const g=JSON.parse('{"title":"为什么评估是第一优先级","description":"Agent 的行为是概率性的，没有评估就无法判断改动是变好还是变坏。本文讲清评估在 Agent 开发中的位置和最小起步方式。","frontmatter":{"title":"为什么评估是第一优先级","description":"Agent 的行为是概率性的，没有评估就无法判断改动是变好还是变坏。本文讲清评估在 Agent 开发中的位置和最小起步方式。"},"headers":[],"relativePath":"guide/14-evaluation/why-evals.md","filePath":"guide/14-evaluation/why-evals.md","lastUpdated":null}'),e={name:"guide/14-evaluation/why-evals.md"};function l(r,t,o,p,d,h){return a(),i("div",null,[...t[0]||(t[0]=[n(`<h1 id="为什么评估是第一优先级" tabindex="-1">为什么评估是第一优先级 <a class="header-anchor" href="#为什么评估是第一优先级" aria-label="Permalink to &quot;为什么评估是第一优先级&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">学习目标</p><ul><li>理解为什么 Agent 开发离不开系统化评估，而&quot;手动试几下&quot;不够用</li><li>区分离线评估、在线评估和人工评审各自解决什么问题</li><li>知道评估要测什么：最终结果、过程轨迹、成本与延迟</li><li>能在项目第一周就搭起一个最小评估闭环</li></ul></div><h2 id="一个常见的场景" tabindex="-1">一个常见的场景 <a class="header-anchor" href="#一个常见的场景" aria-label="Permalink to &quot;一个常见的场景&quot;">​</a></h2><p>你写了一个客服 Agent，测试了十几个问题，效果不错，上线了。两周后，产品同学说&quot;退款问题经常答错&quot;。你改了系统提示词，加了一句&quot;涉及退款时必须先查询订单状态&quot;，手动试了三个退款问题，都对了，发布。</p><p>第二天，有用户反馈：查物流的问题现在也会先去查订单状态，多花了一轮工具调用，响应慢了好几秒；还有一部分售后问题开始答非所问。</p><p>问题出在哪里？不在提示词本身，而在于<strong>你没有办法知道一次改动对整体行为的影响</strong>。三个手动测试只覆盖了你刚想到的情况，而 Agent 的行为空间远比这大。</p><h2 id="agent-为什么特别需要评估" tabindex="-1">Agent 为什么特别需要评估 <a class="header-anchor" href="#agent-为什么特别需要评估" aria-label="Permalink to &quot;Agent 为什么特别需要评估&quot;">​</a></h2><p>传统软件的函数给定输入就有确定输出，单元测试能覆盖主要分支。Agent 不一样：</p><table tabindex="0"><thead><tr><th>特点</th><th>传统软件</th><th>LLM Agent</th></tr></thead><tbody><tr><td>输出确定性</td><td>相同输入相同输出</td><td>同一输入多次运行结果可能不同</td></tr><tr><td>正确性判断</td><td><code>assert a == b</code> 即可</td><td>答案常是自然语言，&quot;对&quot;有多种写法</td></tr><tr><td>影响范围</td><td>改一个函数影响可追踪</td><td>改一句提示词可能影响所有任务</td></tr><tr><td>执行路径</td><td>代码分支固定</td><td>模型自己决定调用哪些工具、调几次</td></tr><tr><td>依赖变化</td><td>依赖版本可锁定</td><td>模型服务端升级，行为可能悄悄变化</td></tr></tbody></table><p>这几点叠加起来，结论很直接：<strong>凭感觉开发 Agent，等于闭着眼睛调参</strong>。你没法回答&quot;这次改动让成功率从多少变到了多少&quot;，也就没法做出可靠的工程决策。</p><p>Anthropic 在 <a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Building effective agents</a> 中也反复强调：先从简单方案开始，用评估衡量效果，只有在评估证明复杂度带来收益时才增加复杂度。没有评估，这条原则根本无法执行。</p><h2 id="评估要测什么" tabindex="-1">评估要测什么 <a class="header-anchor" href="#评估要测什么" aria-label="Permalink to &quot;评估要测什么&quot;">​</a></h2><p>Agent 的评估可以分三层来看：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. 结果层：最终答案对不对？任务完成了没有？    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 2. 过程层：调用了哪些工具？参数对不对？         │</span></span>
<span class="line"><span>│            有没有多余步骤、死循环、越权操作？    │</span></span>
<span class="line"><span>├─────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 3. 代价层：花了多少 Token、多少秒、多少次调用？  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><ul><li><strong>结果层</strong>最重要，也是用户唯一直接感知的。比如&quot;用户问订单 A123 的物流，回答里有正确的快递单号&quot;。</li><li><strong>过程层</strong>用来定位问题和防止隐患。答案对了但调用了一个不该调用的删除工具，这依然是严重缺陷。</li><li><strong>代价层</strong>决定能不能上线。成功率 95% 但每次要 40 秒、花 2 万 Token 的方案，很多场景下不可用。</li></ul><p>只看结果层，你会错过&quot;碰巧答对&quot;和&quot;代价失控&quot;；只看过程层，你会陷入优化中间步骤却不改善最终效果。三层都要有，但第一周可以只做结果层。</p><h2 id="三种评估方式" tabindex="-1">三种评估方式 <a class="header-anchor" href="#三种评估方式" aria-label="Permalink to &quot;三种评估方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>何时进行</th><th>优点</th><th>局限</th></tr></thead><tbody><tr><td>离线评估</td><td>开发时、合并前，跑固定数据集</td><td>可重复、可对比、可放进 CI</td><td>数据集覆盖不到所有真实情况</td></tr><tr><td>在线评估</td><td>上线后，基于真实流量</td><td>反映真实分布</td><td>需要埋点，有延迟，难以做对照</td></tr><tr><td>人工评审</td><td>定期抽样</td><td>最接近真实质量判断</td><td>慢、贵、难规模化</td></tr></tbody></table><p>它们不是互相替代的关系，而是一个循环：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   真实流量 ──(采样 + 人工标注)──► 新的评估用例</span></span>
<span class="line"><span>      ▲                                │</span></span>
<span class="line"><span>      │                                ▼</span></span>
<span class="line"><span>   上线发布 ◄──(通过阈值)── 离线评估 ◄── 代码 / 提示词改动</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>线上发现的失败案例，补进离线数据集；离线数据集守住每一次改动，不让旧问题复发。这个循环转起来，Agent 的质量才会稳步提高，而不是&quot;修一个坏一个&quot;。</p><h2 id="为什么是-第一-优先级" tabindex="-1">为什么是&quot;第一&quot;优先级 <a class="header-anchor" href="#为什么是-第一-优先级" aria-label="Permalink to &quot;为什么是&quot;第一&quot;优先级&quot;">​</a></h2><p>很多团队把评估放在&quot;功能做完之后&quot;。这样做的代价是：</p><ol><li><strong>无法比较方案</strong>。要不要换更大的模型？要不要加 RAG？要不要拆成多 Agent？没有评估，这些讨论只能靠争论和直觉。</li><li><strong>不敢改动</strong>。系统越复杂，越没人敢动提示词，因为不知道会坏掉什么。</li><li><strong>模型升级变成赌博</strong>。厂商发布新版本时，你无法在一小时内回答&quot;能不能切换&quot;。</li><li><strong>问题反馈无法沉淀</strong>。用户报告的 bug 修完就忘，下次改动又会复发。</li></ol><p>反过来，有了评估之后，提示词、模型、工具设计都变成了可以实验的变量：改一处，跑一遍，看数字。这和机器学习里&quot;先定好验证集再训练&quot;是同一个道理。</p><h2 id="第一周的最小评估闭环" tabindex="-1">第一周的最小评估闭环 <a class="header-anchor" href="#第一周的最小评估闭环" aria-label="Permalink to &quot;第一周的最小评估闭环&quot;">​</a></h2><p>不需要一开始就上平台、上 LLM-as-Judge。下面这个起步方式足够大多数项目用上一段时间：</p><ol><li><strong>收集 20~50 个真实用例</strong>。来源可以是产品需求文档里的示例、内测用户的提问、你自己能想到的边界情况。每条写下输入和&quot;什么样算对&quot;。</li><li><strong>用最简单的判定方式</strong>。能精确匹配就精确匹配；不能就检查&quot;回答里是否包含关键事实&quot;、&quot;是否调用了某个工具&quot;。</li><li><strong>写一个脚本批量跑</strong>。输出通过率和失败用例列表，失败用例要能直接看到模型的完整回答。</li><li><strong>每次改动前后都跑</strong>。把结果数字记在提交信息或表格里。</li><li><strong>每修一个 bug 就加一条用例</strong>。</li></ol><p>用例格式可以就是一个 JSONL 文件：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;refund-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我上周买的耳机想退货，订单号 A123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expect_tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get_order&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;must_contain&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;退货&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;track-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;订单 B456 到哪了&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;expect_tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;get_shipping&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;must_not_tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;create_refund&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>具体怎么设计用例和指标、怎么写评估脚本，见下一篇 <a href="/guide/14-evaluation/eval-design">评估集与指标设计</a>。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>只测&quot;开心路径&quot;</strong>。用例全是格式规范、意图清晰的问题，真实用户的错别字、多意图、无关闲聊一个都没有。至少留 20% 用例给边界和对抗情况。</li><li><strong>用例和提示词一起改</strong>。为了让通过率好看而修改期望答案，评估就失去了意义。期望答案变更应当单独评审。</li><li><strong>只跑一次就下结论</strong>。模型输出有随机性，一个用例 5 次里对 3 次，单次运行可能显示&quot;对&quot;也可能显示&quot;错&quot;。关键用例应多次运行看稳定性，或者用 <code>temperature=0</code> 降低（但不能消除）波动。</li><li><strong>把评估当成一次性任务</strong>。数据集不随线上问题更新，几个月后就和真实分布脱节。</li><li><strong>只看总分</strong>。总通过率从 82% 到 83%，可能是 10 个用例变好、9 个变坏。要看逐条差异。</li></ul><h2 id="小测" tabindex="-1">小测 <a class="header-anchor" href="#小测" aria-label="Permalink to &quot;小测&quot;">​</a></h2><ol><li>你把提示词改了一句，手动测了 3 个相关问题都正确。为什么这不足以说明改动是好的？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>因为改动可能影响其他类型的任务（提示词作用于全部请求），而 3 个用例只覆盖了你关心的那一类；同时模型输出有随机性，3 次正确不代表稳定正确。需要在覆盖多种任务的固定数据集上对比改动前后的结果，并检查逐条差异。</p></details><ol start="2"><li>一个 Agent 的最终回答完全正确，但过程中调用了一次 <code>delete_file</code> 工具后又恢复了文件。只看结果层评估会漏掉什么？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>会漏掉过程层的风险：Agent 执行了不必要的危险操作。在生产环境中这类操作可能不可逆，或者恢复失败。过程层评估（检查工具调用序列、禁止调用的工具）能发现这个问题。</p></details><ol start="3"><li>离线评估、在线评估、人工评审之间是什么关系？</li></ol><details class="details custom-block"><summary>查看答案</summary><p>它们互相补充、形成循环：离线评估在每次改动时快速、可重复地守住质量；在线评估反映真实流量下的表现；人工评审提供最可信的质量判断。线上和人工发现的失败案例应补充进离线数据集。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="https://www.anthropic.com/engineering/building-effective-agents" target="_blank" rel="noreferrer">Building effective agents（Anthropic）</a></li><li><a href="https://github.com/openai/evals" target="_blank" rel="noreferrer">OpenAI Evals（GitHub）</a></li><li>本站：<a href="/guide/09-rag/rag-eval">RAG 评估</a>、<a href="/guide/04-prompt/prompt-management">提示词版本管理与测试</a>、<a href="/guide/14-evaluation/llm-judge">LLM-as-Judge</a></li></ul>`,42)])])}const k=s(e,[["render",l]]);export{g as __pageData,k as default};
